select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('version-code','کد نسخه','text',true,10,'{}'),('document-code','کد سند','text',true,20,'{}'),('document-title','عنوان سند','text',true,30,'{}'),('version-number','شماره نسخه','number',true,40,'{}'),('version-label','برچسب نسخه','text',false,50,'{}'),('change-type','نوع تغییر','select',true,60,'{"options":["ایجاد اولیه","اصلاح محتوا","اصلاح ساختار","اصلاح حقوق دسترسی","اصلاح نگارشی","به‌روزرسانی دوره‌ای","بازگشت نسخه"]}'),('change-summary','خلاصه تغییرات','textarea',false,70,'{}'),('change-reference','مرجع تغییر','text',false,80,'{}'),('created-by','ایجادکننده نسخه','text',true,90,'{}'),('created-at','تاریخ ایجاد','text',true,100,'{}'),('effective-at','تاریخ اجرا','text',false,110,'{}'),('approval-code','کد تأیید','text',false,120,'{}'),('file-reference','مرجع فایل نسخه','text',false,130,'{}'),('file-hash','Hash فایل','text',false,140,'{}'),('version-status','وضعیت نسخه','select',true,150,'{"options":["پیش‌نویس","در انتظار تأیید","تأیید شده","نسخه جاری","منسوخ","بازگشت داده شده"]}'),('is-current','نسخه جاری','select',true,160,'{"options":["بله","خیر"]}'),('notes','یادداشت','textarea',false,170,'{}')
) v(k,t,ft,r,s,o) where m.code='43-document-versions' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
