insert into platform_modules(code,title,is_active) values ('43-document-versions','مدیریت نسخه‌های مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده نسخه‌ها','modules:43-document-versions:read'),('write','ثبت نسخه','modules:43-document-versions:write'),('delete','حذف نسخه','modules:43-document-versions:delete'),('submit','ارسال نسخه برای تأیید','modules:43-document-versions:submit'),('approve','تأیید نسخه','modules:43-document-versions:approve'),('publish','جاری‌سازی نسخه','modules:43-document-versions:publish'),('rollback','بازگشت نسخه','modules:43-document-versions:rollback'),('duplicate','تکثیر نسخه','modules:43-document-versions:duplicate')) v(a,t,p) where m.code='43-document-versions' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;